"""Labelled corpus of agent proposals, generated by running the arena engine (imported, never modified) over many seeds.

One row per proposal. Columns (numpy, compact): run, step, agent, env (0 core / 1 tactical / 2 crypto), label, arch, sym, side, qty, limit,
tp, notional, dec (the CODE GATE's decision in that run: 0 allow, 1 hold, 2 refuse), code, replay (repeated idempotency key), trig
(-1 none / 0 unconfirmed / 1 confirmed), kid (idempotency key id within the run), rseed (seed of the synthetic rationale text).

Run metadata (envelopes, regime, sizes) is stored as JSON next to the arrays. The corpus is fully regenerable:
    python -m orderguard_risk build-data           (deterministic; ~2 minutes; full corpus is git-ignored under data/risk/)
The committed `data/risk/sample.npz` holds a few complete runs so the tests and demos work offline.
"""
from __future__ import annotations

import json
import os
import zlib
from pathlib import Path

import numpy as np

from orderguard_arena.agents import DEFAULT_RATES, Agent, PopulationConfig, Proposal, make_population
from orderguard_arena.arena import ArenaConfig, run_arena
from orderguard_arena.envelopes import DEFAULT_LIMITS, PURPOSES, EnvelopeBook, make_envelope, owner_key_from_seed, split_sleeves
from orderguard_arena.feeds import ReplayFeed
from orderguard_guard import ROOT

from .text import rationale

DATA_DIR = Path(os.getenv("OG_RISK_DATA", ROOT / "data" / "risk"))
ENVS = ("core", "tactical", "crypto")
LABELS = ("legit", "collusion", "compromised_oversize", "compromised_sell_all", "compromised_transfer", "compromised_unlisted", "fake_news", "fat_finger",
          "homoglyph", "off_list", "runaway_dup", "runaway_loop", "stale_price", "collusion_stealth")
FAMILY = {"legit": "legit", "collusion": "collusion", "compromised_oversize": "compromised", "compromised_sell_all": "compromised",
          "compromised_transfer": "compromised", "compromised_unlisted": "compromised", "fake_news": "fake_news", "fat_finger": "fat_finger",
          "homoglyph": "off_list", "off_list": "off_list", "runaway_dup": "runaway", "runaway_loop": "runaway", "stale_price": "stale_price", "collusion_stealth": "stealth"}
FAMILIES = ("stealth", "collusion", "compromised", "fat_finger", "runaway", "stale_price", "off_list", "fake_news")
ARCHS = ("momentum", "mean_reversion", "market_maker", "rebalancer", "news_reactive", "llm")
DEC = {"allow": 0, "hold": 1, "refuse": 2}
REGIMES = {"calm": 0.7, "normal": 1.0, "volatile": 1.6, "shifted": 2.2}


def make_book(symbols: list[str], n_agents: int, po: float = 1.0, dm: float = 1.0, bm: float = 1.0) -> EnvelopeBook:
    """default_envelopes with the three knobs scaled (per-order cap, daily cap, price band): more envelope variety for the corpus."""
    key = owner_key_from_seed("owner-1")
    book = EnvelopeBook(key.public_key())
    for name, syms in split_sleeves(symbols).items():
        per_order, daily100, band, su = DEFAULT_LIMITS[name]
        book.add(make_envelope(key, name=name, owner="owner-1", purpose=PURPOSES[name], symbols=syms, per_order=per_order * po,
                               daily=daily100 * max(n_agents, 1) / 100.0 * dm, band_pct=band * bm, step_up=per_order * po * su))
    return book


class StealthColluder(Agent):
    """An ADAPTIVE colluder, defined here (the arena is not modified): it knows the model looks at near-cap sizes, same-ticker bursts and shared
    wording, so it sends honest-sized orders (5-55% of the cap) across the sleeve's tickers at random times and writes honest-sounding text.
    Used only as an out-of-distribution test set ("stealth"), never to train the shipped model."""

    def _collude(self, ctx, step):
        g = self.group
        if not g or not (g["start"] <= step < g["start"] + g["window"]) or self.rng.random() > 0.5:
            return None
        sym = self.symbols[self.rng.randrange(len(self.symbols))]
        px, cap, daily = ctx.last(sym), ctx.collude_cap.get(sym), ctx.collude_daily.get(sym)
        if px is None or cap is None or (daily is not None and g.get("attempted", 0.0) >= 1.5 * daily):
            return None
        qty = max(1, int(cap * self.rng.uniform(0.05, 0.55) / px))
        g["attempted"] = g.get("attempted", 0.0) + qty * px
        return Proposal(step, self.id, self.archetype, self.sleeve, "collusion_stealth",
                        {"ticker": sym, "side": self.rng.choice(("buy", "sell", "buy")), "quantity": qty, "limit_price": round(px * 1.001, 2)}, self._key(step), None, f"group {g['id']}")


class AdaptiveColluder(Agent):
    """A colluder with knobs, for the white-box attacker in `adversary.py` (never used for training). `theta`:
      period, p     inside the group's window it acts on steps where (step + phase) % period == 0, with probability p
      lo, hi        order size as a fraction of the cap the colluders know (the step-up threshold)
      warm          probability per step, OUTSIDE the window, of a tiny order at a random time: it stops the agent from ever having a
                    schedule or a quiet baseline to break (baseline poisoning)
      aggr          how far through the trusted price it limits (honest agents use 0.0005 to 0.003)
      one_ticker    1 = the whole group trades the group's ticker on the buy side (a real position); 0 = random tickers and sides
    It does not run a base strategy: every order it sends is the attacker's and is labelled collusion_stealth."""
    theta: dict = {}

    def propose(self, ctx, snap, step):
        g, th = self.group, self.theta
        if not g:
            return []
        inside = g["start"] <= step < g["start"] + g["window"]
        if not inside:
            if self.rng.random() >= th.get("warm", 0.0):
                return []
            frac = self.rng.uniform(0.002, 0.01)
        else:
            if (step + self.phase) % max(int(th.get("period", 1)), 1) or self.rng.random() > th.get("p", 0.5):
                return []
            frac = self.rng.uniform(th.get("lo", 0.05), th.get("hi", 0.55))
        one = bool(th.get("one_ticker", 0)) and g.get("ticker") in self.symbols
        sym = g["ticker"] if one else self.symbols[self.rng.randrange(len(self.symbols))]
        px, cap = ctx.last(sym), ctx.collude_cap.get(sym)
        if px is None or cap is None:
            return []
        qty = max(1, int(cap * frac / px))
        side = "buy" if one else self.rng.choice(("buy", "sell", "buy"))
        a = th.get("aggr", 0.001)
        return [Proposal(step, self.id, self.archetype, self.sleeve, "collusion_stealth",
                         {"ticker": sym, "side": side, "quantity": qty, "limit_price": round(px * (1 + a if side == "buy" else 1 - a), 2)}, self._key(step), None, f"group {g['id']}")]


def stealth_specs(n: int = 8, base_seed: int = 300) -> list[dict]:
    rng = np.random.default_rng(77)
    return [{"seed": base_seed + i, "agents": int(rng.choice([400, 600, 800, 1000])), "steps": 2000, "steps_per_day": 500, "regime": "stealth",
             "vol": 1.0, "rate_mult": 1.0, "collusion_groups": int(rng.choice([1, 2])), "window": int(rng.choice([250, 400])), "po": 1.0, "dm": float(rng.choice([0.5, 1.0])),
             "bm": 1.0, "fail_prob": 0.15, "stealth": True} for i in range(n)]


def default_specs(n_runs: int = 48, base_seed: int = 100) -> list[dict]:
    """Deterministic run grid: seeds 100.., agent counts, regimes (vol scale), envelope scales, failure/collusion rates. Seed 7 is never used
    (it is the arena's published run, kept for the headline replay)."""
    rng = np.random.default_rng(2024)
    regimes = ["calm"] * 12 + ["normal"] * 14 + ["volatile"] * 12 + ["shifted"] * 10
    regimes = (regimes * 3)[:n_runs] if n_runs > len(regimes) else regimes[:n_runs]
    specs = []
    for i in range(n_runs):
        reg = regimes[i]
        shifted = reg == "shifted"
        specs.append({"seed": base_seed + i, "agents": int(rng.choice([300, 400, 500, 600, 800, 1000])), "steps": 2000, "steps_per_day": 500,
                      "regime": reg, "vol": REGIMES[reg], "rate_mult": float(rng.choice([1.0, 2.0, 3.0] if shifted else [0.5, 1.0, 2.0])),
                      "collusion_groups": int(rng.choice([1, 1, 2, 3])), "window": int(rng.choice([150, 250, 400])),
                      "po": float(rng.choice([0.6, 1.0, 1.0, 1.6, 2.5])), "dm": float(rng.choice([0.5, 1.0, 2.0])),
                      "bm": float(rng.choice([1.0, 1.0, 2.0, 4.0])), "fail_prob": float(rng.choice([0.1, 0.15, 0.25]))})
    return specs


def _rseed(run: int, agent: int, order: dict, label: str) -> int:
    s = f"{run}|{agent}|{order.get('ticker')}|{order.get('side')}|{order.get('quantity')}|{order.get('limit_price')}|{label}"
    return zlib.crc32(s.encode())


def run_spec(spec: dict, run_id: int = 0) -> tuple[dict, dict]:
    """Run the arena for one spec -> ({column: ndarray}, meta). Deterministic."""
    feed = ReplayFeed(spec["seed"], steps=spec["steps"], steps_per_day=spec["steps_per_day"], vol_scale=spec["vol"])
    book = make_book(feed.symbols, spec["agents"], spec["po"], spec["dm"], spec["bm"])
    rates = {k: v * spec["rate_mult"] for k, v in DEFAULT_RATES.items()}
    rates["colluding"] = (spec["collusion_groups"] * 5 + 0.5) / spec["agents"]       # whole groups of 5
    pcfg = PopulationConfig(n=spec["agents"], seed=spec["seed"], rates=rates, fail_prob=spec["fail_prob"], collusion_window=spec["window"])
    agents = make_population(pcfg, split_sleeves(feed.symbols), spec["steps"])
    if spec.get("stealth"):
        agents = [_as_stealth(a) for a in agents]
    if spec.get("adaptive"):
        agents = [_as_stealth(a, AdaptiveColluder, spec["adaptive"]) for a in agents]
    cfg = ArenaConfig(seed=spec["seed"], agents=spec["agents"], steps=spec["steps"], steps_per_day=spec["steps_per_day"], rates=rates,
                      fail_prob=spec["fail_prob"], keep_events=True)
    res = run_arena(cfg, feed=feed, book=book, agents=agents)
    meta = {"spec": spec, "run": run_id, "digest": res.summary["digest"], "symbols": feed.symbols,
            "envelopes": [{"name": e["name"], "per_order": e["per_order"], "daily": e["daily"], "band_pct": e["band_pct"], "step_up": e["step_up"],
                           "symbols": e["symbols"]} for e in res.summary["envelopes"]]}
    return events_to_columns(res.events, {a.id: a.archetype for a in res.agents}, run_id, feed.symbols), meta


def _as_stealth(a, cls=None, theta=None):
    if a.failure != "colluding":
        return a
    cls = cls or StealthColluder
    b = cls.__new__(cls)
    b.__dict__.update(a.__dict__)
    if theta is not None:
        b.theta = dict(theta)
    return b


def events_to_columns(events: list[dict], arch_of: dict, run_id: int, symbols: list[str]) -> dict:
    n = len(events)
    sym_ix = {s: i for i, s in enumerate(symbols)}
    c = {"run": np.full(n, run_id, np.int16), "step": np.zeros(n, np.int32), "agent": np.zeros(n, np.int32), "env": np.zeros(n, np.int8),
         "label": np.zeros(n, np.int8), "arch": np.zeros(n, np.int8), "sym": np.zeros(n, np.int16), "side": np.zeros(n, np.int8),
         "qty": np.zeros(n, np.float64), "limit": np.zeros(n, np.float32), "tp": np.full(n, np.nan, np.float32), "notional": np.zeros(n, np.float32),
         "dec": np.zeros(n, np.int8), "code": np.zeros(n, "U10"), "replay": np.zeros(n, np.bool_), "trig": np.full(n, -1, np.int8),
         "kid": np.zeros(n, np.int32), "rseed": np.zeros(n, np.uint32), "ticker": np.zeros(n, "U12")}
    kids: dict[str, int] = {}
    for i, e in enumerate(events):
        o = e["order"]
        c["step"][i], c["agent"][i] = e["step"], e["agent"]
        c["env"][i] = ENVS.index(e["sleeve"])
        c["label"][i] = LABELS.index(e["label"])
        c["arch"][i] = ARCHS.index(arch_of.get(e["agent"], "momentum"))
        t = o.get("ticker")
        c["ticker"][i] = "" if t is None else t
        c["sym"][i] = sym_ix.get(t, -1)
        c["side"][i] = {"buy": 0, "sell": 1}.get(o.get("side"), 2)
        c["qty"][i] = float(o.get("quantity") or 0)
        c["limit"][i] = float(o.get("limit_price") or 0.0)
        if e.get("tp") is not None:
            c["tp"][i] = e["tp"]
        c["notional"][i] = e["risk"]
        c["dec"][i] = DEC[e["d"]]
        c["code"][i] = e.get("code") or ""
        c["replay"][i] = bool(e.get("replay"))
        if "trigger" in e:
            c["trig"][i] = 1 if e["trigger"].get("confirmed") else 0
        c["kid"][i] = kids.setdefault(e["key"], len(kids))
        c["rseed"][i] = _rseed(run_id, e["agent"], o, e["label"])
        if o.get("type") == "transfer" or "destination_account" in o:
            c["side"][i] = 3
    return c


def build(specs: list[dict], workers: int = 0, progress=None) -> tuple[dict, list[dict]]:
    outs = []
    pool_ok = bool(workers and workers > 1)
    if pool_ok:
        try:
            from concurrent.futures import ProcessPoolExecutor
            with ProcessPoolExecutor(workers) as ex:
                outs = list(ex.map(_job, [(s, i) for i, s in enumerate(specs)]))
        except (PermissionError, OSError):                       # sandboxes without semaphores: run serially
            pool_ok = False
    if not pool_ok:
        for i, s in enumerate(specs):
            outs.append(_job((s, i)))
            if progress:
                progress(i + 1, len(specs))
    cols = {k: np.concatenate([o[0][k] for o in outs]) for k in outs[0][0]}
    return cols, [o[1] for o in outs]


def _job(a):
    return run_spec(a[0], a[1])


def save(path: str | Path, cols: dict, metas: list[dict]) -> None:
    np.savez_compressed(path, meta=np.array(json.dumps(metas, sort_keys=True)), **cols)


def load(path: str | Path) -> tuple[dict, list[dict]]:
    z = np.load(path, allow_pickle=False)
    metas = json.loads(str(z["meta"]))
    return {k: z[k] for k in z.files if k != "meta"}, metas


def corpus_path() -> Path:
    return DATA_DIR / "corpus.npz"


def sample_path() -> Path:
    return DATA_DIR / "sample.npz"


def load_corpus() -> tuple[dict, list[dict]]:
    """The full corpus if present, else the committed sample."""
    p = corpus_path() if corpus_path().exists() else sample_path()
    return load(p)


def texts(cols: dict, idx=None) -> list[str]:
    """Synthetic rationale per row (deterministic from the stored seed)."""
    ix = range(len(cols["run"])) if idx is None else idx
    out = []
    for i in ix:
        lab = LABELS[cols["label"][i]]
        usd = float(cols["notional"][i])
        out.append(rationale(lab, ARCHS[cols["arch"][i]], str(cols["ticker"][i]), ("buy", "sell", "buy", "buy")[cols["side"][i]], usd, int(cols["rseed"][i])))
    return out
